@startuml

class Provider {
  + name : string
  + location : string
}

class Cruise {
  + number : int
  + name : string
  + startDate : date
  + endDate : date
}

class Employee {
  + name : string
  + socialSecurityNumber : string
}

class Guest {
  + name : string
  + isVIP : boolean
}

class Ship {
  + name : string
  + numberOfDecks : int
  + length : float
  + numberOfPassengers : int
}

class TravelAgency {
  + name : string
  + address : string
}

class Booking {
  + bookingNumber : string
  + bookingDate : date
}

class DestinationArea {
  + name : string
  + seaName : string
}

class Show {
  + title : string
  + duration : int
}

class Ticket {
}

Provider "1" -- "*" Cruise : organizes
Cruise "*" -- "*" Employee : requires
Cruise "*" -- "*" Guest : involves
Cruise "*" -- "1" Ship : uses
Cruise "*" -- "1" DestinationArea : heads for
Cruise "1" -- "*" Show : offers
Cruise "1" -- "*" Ticket : issues
Guest "1" -- "*" Ticket : holds
Booking "*" -- "1" Cruise : for
Booking "*" -- "1" TravelAgency : through
TravelAgency "1" -- "*" Booking : manages

@enduml

